import{_ as i,l as s,o as a,c as l,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"调试器与断点","description":"","frontmatter":{"title":"调试器与断点","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/debugger-breakpoint.md","filePath":"cs/debugger-breakpoint.md","lastUpdated":1789023840000}'),E={name:"cs/debugger-breakpoint.md"};function A(h,e,B,_,u,m){const o=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="调试器与断点" tabindex="-1">调试器与断点 <a class="header-anchor" href="#调试器与断点" aria-label="Permalink to &quot;调试器与断点&quot;">​</a></h1><div class="epigraph"><p>断点把进程停在某条指令上；调试器靠符号表把地址翻译回函数与行号，从而对照源码与寄存器。</p><footer>—— 据 Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective；ISO/IEC 9899 整理</footer></div><p>上一课<a href="/cs/preprocessor-preview">预处理器</a>说明编译器看见的是展开后的文本。本课不重讲宏，也不从某一种调试器命令手册另起。缺口是：程序已经能链接运行，失败时需要把抽象机器上的状态<strong>重新对准源码里的名字</strong>。断点、单步与打印变量，依赖编译时留下的调试信息。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程停在入口之后，CPU 只看见地址。要把「停在 <code>foo</code> 第 12 行」说出来，镜像或旁路文件里必须有：函数名与地址范围、行号与指令的映射、局部变量在栈帧里的位置。缺口因此不是图形界面，而是<strong>符号如何把机器状态映回源码</strong>。没有 <code>-g</code> 一类调试信息，断点只能打在原始地址上，栈回溯只剩十六进制。</p><p>优化会让映射变糊：变量被放进寄存器或被消除，行号对应的指令被重排。这不是调试器坏了，是抽象机器与优化后的指令序列不再一行对一条。对照未定义行为课：优化后「不可能」的路径消失，断点也可能打不中你以为还在的行。</p><h3 id="断点不是-printf" tabindex="-1">断点不是 <code>printf</code> <a class="header-anchor" href="#断点不是-printf" aria-label="Permalink to &quot;断点不是 `printf`&quot;">​</a></h3><p><code>printf</code> 改程序、改时序、改缓冲，失败路径上还可能自己失败。断点在进程外改控制流：插入陷阱指令或用硬件断点寄存器，命中后把控制交给调试器。观察点可以在某地址被写时停。这些不插入源码，因此更接近「原程序」——但仍改变时序，竞态可能被掩盖或被放大。本课在单线程里用它查看栈帧与指针。</p><p><span class="marginnote">CSAPP 用 GDB 把机器级程序与源码对照。ISO C 不规定调试器；调试信息格式（DWARF 等）是工具链约定。本课不把内核调试另起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>带调试信息编译，加载进调试器，在函数或行上设断点，运行至命中，查看当前帧的参数与局部、调用栈上的返回地址链。这正是递归课那叠帧的现场版。指针值对照寿命：若对象已 <code>free</code>，地址仍可能「能读」，不能据此宣称程序合法。</p>',11)),(a(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E8%B0%83%E8%AF%95%E7%AC%A6%E5%8F%B7%22%5D%20--%3E%20MAP%5B%22%E5%9C%B0%E5%9D%80%E6%98%A0%E5%88%B0%E5%87%BD%E6%95%B0%E4%B8%8E%E8%A1%8C%22%5D%0A%20%20BP%5B%22%E6%96%AD%E7%82%B9%EF%BC%9A%E5%9C%B0%E5%9D%80%E4%B8%8A%E7%9A%84%E9%99%B7%E9%98%B1%22%5D%20--%3E%20STOP%5B%22%E8%BF%9B%E7%A8%8B%E5%81%9C%E4%B8%8B%22%5D%0A%20%20STOP%20--%3E%20FRAME%5B%22%E8%AF%BB%E5%BD%93%E5%89%8D%E6%A0%88%E5%B8%A7%22%5D%0A%20%20MAP%20--%3E%20FRAME%0A%20%20FRAME%20--%3E%20SRC%5B%22%E5%AF%B9%E7%85%A7%E6%BA%90%E7%A0%81%E4%B8%AD%E7%9A%84%E5%90%8D%E5%AD%97%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>核心转储是事后的同一张图：当时的寄存器与内存，配上同一份符号才能读。没有符号，只剩原始地址空间——后课进程布局会告诉那些段是什么，仍对不上局部变量名。</p><p>没有符号时仍可在入口地址下断，但局部变量只能当栈槽偏移来猜，等价于手算调用约定。剥离符号的发行版要保留一份未剥离的镜像专供事后分析，否则核心转储只能对照当时的构建标识去找。条件断点用表达式过滤命中，本身会大幅改变时序，查竞态时要当成另一种探针。本课单线程：把断点当「打印但不改源码」的手段，用来核对帧、指针与寿命，而不是当性能剖析器。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>软件断点改代码段里的一字节为陷阱，继续执行前要写回原指令。自修改与写保护会使这条路径更复杂；用户态调试器通常请内核代劳。单步是临时断点打在下一条，或用硬件单步标志。理解这些，才理解为何在只读代码映射上设断点需要权限，以及为何动态链接的共享库里的断点要等库被加载后才能解析符号。</p><p>优化与内联会让「当前行」对应一段已被拆散的指令，参数可能不在栈上而在寄存器里，甚至已被重用。这时应当下降到反汇编对照调用约定，而不是认定调试器坏了。观察点（watch）在数据地址上停，适合查「谁写了这个指针」——别名课的现场工具。核心转储配同一份未剥离符号的镜像，才能把当时的指令指针译回函数；剥离后的发行版只剩地址，必须用当时的构建产物对照。后课构建系统要保证你调试的就是图上那一份，而不是磁盘上另一份旧 <code>a.out</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲反向调试与时间旅行，不把反汇编当 ISA 课。下一课<a href="/cs/build-system">构建系统</a>保证你调试的二进制与此刻源码对应。后课默认：断点停在指令地址；符号把地址译回名字；优化会削弱对应关系。没有符号的发行版要把未剥离镜像另行保存，否则事后只能对着地址猜。</p><p>硬件断点数量有限，软件断点依赖代码页可写或内核协助。对只读共享库下断，调试器通常把页临时改为可写再写回陷阱，继续时还原。这不改变源码级契约，但会让「程序未被改写」在机器上暂时为假。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调试器靠符号把地址映回函数、行与栈槽。</li><li>断点是地址上的陷阱，不替代契约，也不证明无 UB。</li><li>优化使行号与变量位置变得近似；核心转储也要同一份符号。</li><li>下一课用构建图保证被调试的镜像来自当前源。</li><li>出处：CSAPP 对 GDB 与机器级对照；工具链调试信息约定。</li></ul>',10))])}const b=i(E,[["render",A]]);export{P as __pageData,b as default};
